head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col2": "a1fewfekwlmfefewl",
        "col3": "a1",
        "depth": "0"
    }, {
        "col2": "a1-1",
        "col3": "a1-1",
        "depth": "1"
    }, {
        "col2": "a2",
        "col3": "a2",
        "depth": "0"
    }, {
        "col2": "a2-1",
        "col3": "a2-1",
        "depth": "1"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'gridView1_tooltip').style.display == 'block';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. 브라우저에서 image 컬럼(name3)을 마우스오버한다.
    //4. In your browser, mouse over the image column (name3)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'gridView1_cell_0_1')");
    // verify step noImageTooltip 속성이 적용되어 image 컬럼에서는 tooltip 이 나타나지 않는다.
    //4. The noImageTooltip attribute is applied and the tooltip does not appear in the image column.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
